package dev.macasino.game;

import java.util.UUID;

/**
 * Craps table: pure server-side dice game logic.
 *
 * <p>A player places a bet, then rolls two dice. The total of the two dice determines
 * the outcome:
 * <ul>
 *   <li>7 or 11 on the come-out: win even money</li>
 *   <li>2, 3, or 12 on the come-out: lose everything</li>
 *   <li>Any other number establishes a point; roll again until the point repeats (win)
 *       or a 7 appears (lose)</li>
 * </ul>
 *
 * <p>All numbers are generated by a server-owned {@link java.util.Random} seeded per
 * roll, so a client cannot influence the outcome.
 */
public class CrapsTable {

    public static final int MIN_BET = 10;
    public static final int MAX_BET = 10_000;

    private final java.util.Random rng = new java.util.Random();
    private final java.util.Map<UUID, Long> bets = new java.util.concurrent.ConcurrentHashMap<>();
    private final java.util.Map<UUID, Integer> lastRoll = new java.util.concurrent.ConcurrentHashMap<>();
    private final java.util.Map<UUID, Long> lastPayout = new java.util.concurrent.ConcurrentHashMap<>();
    private final java.util.Map<UUID, Integer> point = new java.util.concurrent.ConcurrentHashMap<>();
    private final java.util.Map<UUID, Boolean> phase = new java.util.concurrent.ConcurrentHashMap<>(); // true = POINT phase

    /** Place a bet for a player. Returns false if the seat is unknown, the stake is
     * out of range, or the player cannot afford it. */
    public boolean placeBet(UUID playerId, long amount) {
        if (amount < MIN_BET || amount > MAX_BET) return false;
        bets.put(playerId, amount);
        return true;
    }

    /** Roll two dice for a player and resolve the outcome. Returns the total rolled. */
    public int roll(UUID playerId) {
        Long bet = bets.get(playerId);
        if (bet == null || bet <= 0) return -1;

        int d1 = rng.nextInt(6) + 1;
        int d2 = rng.nextInt(6) + 1;
        int total = d1 + d2;
        lastRoll.put(playerId, total);

        Integer currentPoint = point.get(playerId);
        boolean inPointPhase = currentPoint != null;

        long payout;
        if (!inPointPhase) {
            // Come-out roll
            if (total == 7 || total == 11) {
                payout = bet * 2; // win even money
                lastPayout.put(playerId, payout);
                point.remove(playerId);
                phase.put(playerId, false);
            } else if (total == 2 || total == 3 || total == 12) {
                payout = 0; // lose
                lastPayout.put(playerId, payout);
                point.remove(playerId);
                phase.put(playerId, false);
            } else {
                // Establish point
                point.put(playerId, total);
                phase.put(playerId, true);
                payout = 0; // no payout yet, point established
                lastPayout.put(playerId, payout);
            }
        } else {
            // Point phase
            if (total == currentPoint) {
                payout = bet * 2; // win even money
                lastPayout.put(playerId, payout);
                point.remove(playerId);
                phase.put(playerId, false);
            } else if (total == 7) {
                payout = 0; // seven out
                lastPayout.put(playerId, payout);
                point.remove(playerId);
                phase.put(playerId, false);
            } else {
                payout = 0; // roll again
                lastPayout.put(playerId, payout);
            }
        }

        return total;
    }

    /** Get the last roll total for a player, or -1 if no roll has occurred. */
    public int getLastRoll(UUID playerId) {
        return lastRoll.getOrDefault(playerId, -1);
    }

    /** Get the last payout for a player, or 0 if none. */
    public long getLastPayout(UUID playerId) {
        return lastPayout.getOrDefault(playerId, 0L);
    }

    /** Get the current point for a player, or 0 if no point is established. */
    public int getPoint(UUID playerId) {
        return point.getOrDefault(playerId, 0);
    }

    /** Check if a player is in the point phase. */
    public boolean isInPointPhase(UUID playerId) {
        return Boolean.TRUE.equals(phase.get(playerId));
    }

    /** Get the bet amount for a player, or 0 if none. */
    public long getBet(UUID playerId) {
        return bets.getOrDefault(playerId, 0L);
    }

    /** Clear a player's bet (refund). */
    public long clearBet(UUID playerId) {
        Long bet = bets.remove(playerId);
        point.remove(playerId);
        phase.remove(playerId);
        return bet != null ? bet : 0L;
    }
}
